  function showPersonModal(id,forcedRole){const arr=getUsers(),p=id?byId(arr,id):null;modal(p?'Modifier le personnel':'Ajouter au personnel',`<form id="personForm" class="form-grid"><div class="field"><label>Nom complet *</label><input name="name" value="${esc(p?.name||'')}" required></div><div class="field"><label>Téléphone de connexion *</label><input name="phone" value="${esc(p?.phone||'')}" required></div><div class="field"><label>Rôle *</label><select name="role">${['admin','bureau','tech'].map(r=>`<option value="${r}" ${(forcedRole||p?.role)===r?'selected':''}>${LABELS[r]}</option>`).join('')}</select></div><div class="field"><label>Fonction / titre</label><input name="title" value="${esc(p?.title||'')}"></div><div class="field"><label>Statut</label><select name="active"><option value="1" ${p?.active!==false?'selected':''}>Actif</option><option value="0" ${p?.active===false?'selected':''}>Inactif</option></select></div><div class="form-actions full"><button class="btn btn-primary">Enregistrer</button></div></form>`);$('#personForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),phone=PerrasAuth.normalizePhone(fd.get('phone'));if(arr.some(x=>x.id!==p?.id&&PerrasAuth.normalizePhone(x.phone)===phone))return alert('Ce numéro est déjà utilisé par un autre compte.');const obj={id:p?.id||PerrasDB.uid('u'),name:fd.get('name'),phone,role:fd.get('role'),title:fd.get('title'),active:fd.get('active')==='1',truckId:p?.truckId||''};if(p)Object.assign(p,obj);else arr.push(obj);PerrasDB.set('users',arr);audit(p?'Modification':'Création','Personnel',obj.name);closeModal();toast('Personnel enregistré. Le numéro peut maintenant recevoir un code de connexion.');render();}}
  function showTruckModal(id){const arr=PerrasDB.get('trucks')||[],t=id?byId(arr,id):null;const techs=getUsers().filter(u=>u.role==='tech'&&u.active);modal(t?'Modifier le camion':'Ajouter un camion',`<form id="truckForm" class="form-grid"><div class="field"><label>Numéro *</label><input name="number" value="${esc(t?.number||'')}" required></div><div class="field"><label>Description *</label><input name="description" value="${esc(t?.description||'')}" required></div><div class="field"><label>Technicien assigné</label><select name="assignedUserId"><option value="">Aucun</option>${techs.map(x=>`<option value="${x.id}" ${x.id===t?.assignedUserId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Statut</label><select name="active"><option value="1" ${t?.active!==false?'selected':''}>Actif</option><option value="0" ${t?.active===false?'selected':''}>Inactif</option></select></div><div class="form-actions full"><button class="btn btn-primary">Enregistrer</button></div></form>`);$('#truckForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),obj={id:t?.id||PerrasDB.uid('t'),number:fd.get('number'),description:fd.get('description'),assignedUserId:fd.get('assignedUserId'),active:fd.get('active')==='1'};if(t)Object.assign(t,obj);else arr.push(obj);PerrasDB.set('trucks',arr);const users=getUsers();users.filter(u=>u.role==='tech').forEach(u=>{if(u.truckId===obj.id)u.truckId=''});const tech=byId(users,obj.assignedUserId);if(tech)tech.truckId=obj.id;PerrasDB.set('users',users);audit(t?'Modification':'Création','Camion',obj.number);closeModal();toast('Camion enregistré.');render();}}

