    clientSel.onchange=()=>{const cl=byId(getClients(),clientSel.value);if(cl&&!isEdit)address.value=cl.address||'';};type.onchange=()=>{inv.classList.toggle('hidden',type.value!=='Facture');inv.querySelector('input').required=type.value==='Facture';};type.onchange();form.querySelector('[data-close2]').onclick=closeModal;
