  function printServiceDocument(id,type){
    const c=byId(PerrasDB.get('serviceCalls')||[],id),cl=byId(getClients(),c?.clientId),tech=byId(getUsers(),c?.techId);if(!c)return;const title=type==='BT'?`Bon de travail ${c.id.toUpperCase()}`:`Facture ${c.invoiceNumber||c.id}`;const w=window.open('','_blank','width=900,height=800');if(!w)return alert('Autorisez les fenêtres contextuelles pour imprimer / créer le PDF.');w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Arial,sans-serif;color:#17324a;padding:36px}h1{color:#0b6fd3}.head{display:flex;justify-content:space-between;border-bottom:2px solid #0b6fd3;padding-bottom:16px}.box{border:1px solid #dbe5ee;border-radius:10px;padding:16px;margin-top:16px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.muted{color:#6a7d90}@media print{button{display:none}}</style></head><body><div class="head"><div><h1>PERRAS</h1><div>PLOMBERIE · CHAUFFAGE · CONFIANCE</div></div><div><strong>${esc(title)}</strong><br>${dateOnly(c.date)}</div></div><div class="grid"><div class="box"><h3>Client</h3><strong>${esc(cl?.name||'')}</strong><br>${esc(PerrasAuth.formatPhone(cl?.phone||''))}<br>${esc(c.address)}</div><div class="box"><h3>Intervention</h3>PO: ${esc(c.poNumber||'—')}<br>Technicien: ${esc(tech?.name||'—')}<br>Heure: ${esc(c.time)} · ${formatDuration(c.duration)}<br>État: ${esc(c.status)}</div></div><div class="box"><h3>Description</h3>${esc(c.description)}</div>${type==='BT'?`<div class="box"><h3>Travaux effectués</h3>${esc(c.work||'—')}<h3>Pièces / matériel</h3>${esc(c.parts||'—')}<h3>Notes</h3>${esc(c.notes||'—')}</div>`:`<div class="box"><h3>Notes d’intervention</h3>${esc(c.notes||'—')}</div>`}<p class="muted">Document généré depuis Perras ERP.</p><button onclick="window.print()">Imprimer / Enregistrer en PDF</button></body></html>`);w.document.close();setTimeout(()=>w.print(),250);audit('Impression PDF',type,c.id);
  }
