  function saveRoles(e){e.preventDefault();const fd=new FormData(e.target),p=permissions(),modules=allRoleModules();['admin','bureau','tech'].forEach(r=>{p[r]=p[r]||{};modules.forEach(m=>{const key=`perm_${r}_${m.route}`;if(fd.has(key))p[r][m.route]=fd.get(key)==='1';});});PerrasDB.set('permissions',p);audit('Modification','Rôles & droits','Permissions par rôle mises à jour');toast('Droits d’accès enregistrés.');renderMenu();render();}



  /* ===== V3 ADMIN — calendrier, appels, achats, fournisseurs et prix ===== */
  if(!CALL_STATUSES.includes('Vérification')) CALL_STATUSES.splice(2,0,'Vérification');
