    const host=$('#supplierCategoryRows');originalCats.forEach(c=>appendSupplierCategoryRow(host,{id:c.id,name:c.name,rebate:s?.rebates?.[c.id]||0}));if(!originalCats.length)appendSupplierCategoryRow(host);$('#addSupplierCatRow').onclick=()=>appendSupplierCategoryRow(host);
    $('#supplierForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),rows=[...host.querySelectorAll('.supplier-cat-row')],used=new Set(),cats=[];rows.forEach(r=>{const name=r.querySelector('[data-cat-name]').value.trim();if(!name)return;let cid=r.dataset.catId||PerrasDB.uid('cat');while(used.has(cid))cid=PerrasDB.uid('cat');used.add(cid);cats.push({id:cid,name,rebate:Number(r.querySelector('[data-cat-rebate]').value||0)});});const kept=new Set(cats.map(c=>c.id)),removed=originalCats.map(c=>c.id).filter(cid=>!kept.has(cid));const all=PerrasDB.get('suppliers')||[];all.forEach(x=>{x.rebates=x.rebates||{};removed.forEach(cid=>delete x.rebates[cid]);cats.forEach(c=>{if(x.rebates[c.id]===undefined)x.rebates[c.id]=0;});});let target=s?byId(all,s.id):null;if(!target){target={id:PerrasDB.uid('sup'),rebates:{}};all.push(target);}target.name=String(fd.get('name')||'').trim();target.paymentTerms=String(fd.get('paymentTerms')||'').trim();target.paymentDiscountPct=Number(fd.get('paymentDiscountPct')||0);target.discountDays=Number(fd.get('discountDays')||0);target.netDays=Number(fd.get('netDays')||0);target.capitalYieldPct=Number(fd.get('capitalYieldPct')||0);target.rebates=target.rebates||{};cats.forEach(c=>target.rebates[c.id]=c.rebate);PerrasDB.set('supplierCategories',cats.map(({id,name})=>({id,name})));PerrasDB.set('suppliers',all);recalculatePricingDiscounts();audit(s?'Modification':'Création','Fournisseur',`${target.name} — rabais/termes enregistrés`);closeModal();toast('Fournisseur enregistré et prix recalculés.');render();};
