  function productCards(products,q=''){q=q.toLowerCase();const pricing=PerrasDB.get('pricing')||{},supplierCats=PerrasDB.get('supplierCategories')||[],rows=products.filter(p=>[p.code,p.description,p.category].join(' ').toLowerCase().includes(q));return `<div class="product-grid">${rows.map(p=>{const [state,cls]=productState(p),pc=supplierCats.find(c=>c.id===p.supplierCategoryId),pricingKey=pc?.name||p.category,disc=Number(pricing.calculatedDiscounts?.[pricingKey]?.['Perras 1']??pricing.discounts?.['Perras 1']??0),sell=Number(p.listPrice||0)*(1-disc/100);return `<article class="product-card ${p.active===false?'inactive-product':''}"><div class="product-visual">${p.image?`<img src="${esc(p.image)}" alt="">`:`<span>${productIcon(p.category)}</span>`}</div><div class="product-card-body"><div class="product-code">${esc(p.code)}</div><h3>${esc(p.description)}</h3><div class="small muted">${esc(p.category)}${pc?` · Tarification : ${esc(pc.name)}`:''}</div><div class="product-stock"><span class="badge badge-${cls}">${state}</span><strong>${p.warehouseQty} en stock</strong>${p.onOrderQty?`<span class="small">${p.onOrderQty} en commande</span>`:''}</div><div class="product-prices"><div><span>Prix Liste</span><strong>${money(p.listPrice)}</strong></div><div><span>Perras 1</span><strong>${money(sell)}</strong><small>${disc.toFixed(2)} % d’escompte</small></div></div><div class="actions"><button class="btn btn-outline btn-sm" data-action="edit-product" data-id="${p.id}">Modifier</button><button class="btn btn-outline btn-sm" data-action="toggle-product-active" data-id="${p.id}">${p.active===false?'Réactiver':'Inactif'}</button></div></div></article>`}).join('')||'<div class="empty">Aucun produit trouvé.</div>'}</div>`;}

