      if(act==='calendar-prev'){adminUI.calendarDate=addDaysISO(adminUI.calendarDate||PerrasDB.todayISO(),-1);adminUI.calendarMonth=adminUI.calendarDate.slice(0,7)+'-01';render();}
      if(act==='calendar-next'){adminUI.calendarDate=addDaysISO(adminUI.calendarDate||PerrasDB.todayISO(),1);adminUI.calendarMonth=adminUI.calendarDate.slice(0,7)+'-01';render();}
      if(act==='calendar-month-prev'){adminUI.calendarMonth=addMonthsISO(adminUI.calendarMonth,-1);render();}
      if(act==='calendar-month-next'){adminUI.calendarMonth=addMonthsISO(adminUI.calendarMonth,1);render();}
      if(act==='calendar-day'){adminUI.calendarDate=a.dataset.date;adminUI.calendarMonth=a.dataset.date.slice(0,7)+'-01';render();}
      if(act==='call-view'){adminUI.callView=a.dataset.view;render();}
