    if(route==='products'){$('#productSearch').oninput=e=>$('#productCardsHost').innerHTML=productCards(PerrasDB.get('products')||[],e.target.value);}
    if(route==='suppliers'){const yf=$('#supplierYieldForm');if(yf)yf.onsubmit=saveSupplierYield;}
