  function btTableMarkup(calls,q=''){const clients=getClients();q=q.toLowerCase();const rows=calls.filter(c=>[c.btNumber,c.id,c.poNumber,c.date,c.address,c.description,c.status,byId(clients,c.clientId)?.name].join(' ').toLowerCase().includes(q));return `<div class="table-wrap"><table class="table"><thead><tr><th>No BT</th><th>PO</th><th>Date</th><th>Client</th><th>Adresse</th><th>État</th><th>PDF</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><strong>${esc(c.btNumber||c.id.toUpperCase())}</strong></td><td>${esc(c.poNumber||'—')}</td><td>${dateOnly(c.date)}<div class="small muted">${esc(c.time)}</div></td><td>${esc(byId(clients,c.clientId)?.name||'—')}</td><td>${esc(c.address)}</td><td>${badge(c.status)}</td><td><button class="btn btn-outline btn-sm" data-action="print-bt" data-id="${c.id}">PDF / Imprimer</button></td><td><button class="btn btn-primary btn-sm" data-action="open-bt" data-id="${c.id}">${user.role==='tech'?'Ouvrir':'Détails'}</button></td></tr>`).join('')||'<tr><td colspan="8"><div class="empty">Aucun BT trouvé.</div></td></tr>'}</tbody></table></div>`;}
