    const m=modalRoot.querySelector('.modal');if(m)m.style.width='min(1180px,100%)';
    const ch=$('#supplierCategoryRows');originalCats.forEach(c=>appendSupplierCategoryRow(ch,{id:c.id,name:c.name,rebate:s?.rebates?.[c.id]||0}));if(!originalCats.length)appendSupplierCategoryRow(ch);$('#addSupplierCatRow').onclick=()=>appendSupplierCategoryRow(ch);
