    form.onsubmit=e=>{e.preventDefault();const fd=new FormData(form),s=byId(suppliers,fd.get('supplierId')),items=collectPOItems(host),oldItems=po?JSON.parse(JSON.stringify(po.items||[])):[],oldStatus=po?.status||'Fermé',newNumber=po?String(fd.get('number')).trim():consumeDocNumber('po');if(!/^\d{2}-\d{4}$/.test(newNumber))return alert('Le numéro doit respecter le format 26-XXXX, 27-XXXX, etc.');const obj={id:po?.id||PerrasDB.uid('po'),number:newNumber,buyerId:fd.get('buyerId'),date:fd.get('date'),supplierId:fd.get('supplierId'),supplier:s?.name||'',status:fd.get('status'),total:Number(fd.get('total')||0),lines:fd.get('lines'),items};syncProductOnOrder(oldItems,oldStatus,items,obj.status);if(po)Object.assign(po,obj);else arr.unshift(obj);PerrasDB.set('purchaseOrders',arr);audit(po?'Modification':'Création','Bon de commande',obj.number);closeModal();toast('Bon de commande enregistré et quantités en commande mises à jour.');render();};
