    const requestRows=requests.map(r=>{const p=byId(products,r.productId),isBack=r.source==='Back order';return `<tr><td><span class="badge ${isBack?'badge-orange':'badge-blue'}">${isBack?'Back order':'Demande tech'}</span></td><td><strong>${esc(p?.code||'—')}</strong></td><td>${esc(p?.description||r.description||'Produit non répertorié')}<div class="small muted">${esc(r.note||'')}</div></td><td>${p?.warehouseQty??'—'}</td><td>${p?.minQty??'—'}</td><td>${p?.onOrderQty??'—'}</td><td><strong>${r.qty||1}</strong></td><td>${isBack?'Réception PO':esc(byId(users,r.userId)?.name||'Technicien')}</td></tr>`}).join('');
