  /* ===== V29 — CATALOGUE ASYNCHRONE : aucun gel de menu ===== */
  let productLoadRerenderPending=false;
  function productLoadingMarkup(title='Chargement du catalogue'){
    const st=PerrasDB.productStatsCached?.()||{};
    const count=Number(st.total||0);
    return `<div class="card"><div class="card-body catalog-loading"><div class="catalog-spinner"></div><h3>${esc(title)}</h3><p class="muted">Le catalogue se charge en arrière-plan. Les autres menus restent utilisables.</p>${count?`<span class="badge badge-blue">${count.toLocaleString('fr-CA')} produits</span>`:''}</div></div>`;
  }
  function ensureProductsAsyncFor(route){
    if(PerrasDB.productsReady?.()) return true;
    if(!productLoadRerenderPending){
      productLoadRerenderPending=true;
      PerrasDB.loadProductsAsync().then(()=>{
        productLoadRerenderPending=false;
        const r=currentRoute();
        if(['products','inventory','mytruck','requestproduct','orders','reports','bt','invoices','forms','quotes'].includes(r)) render();
      }).catch(err=>{
        productLoadRerenderPending=false;
        console.error(err);
        toast('Erreur de chargement du catalogue.');
      });
    }
    return false;
  }

  /* ===== V25 — PERFORMANCE CATALOGUE 22 000+ PRODUITS ===== */
  const perfV25={productPage:1,productPageSize:48,productQuery:'',inventoryPage:1,inventoryPageSize:100,inventoryQuery:''};
  function pageCountV25(total,size){return Math.max(1,Math.ceil(Number(total||0)/Number(size||1)));}
  function pagerV25(total,page,size,action){
    const pages=pageCountV25(total,size),p=Math.max(1,Math.min(page,pages)),start=total?((p-1)*size+1):0,end=Math.min(total,p*size);
    return `<div class="catalog-pager"><div class="small muted">${start.toLocaleString('fr-CA')}–${end.toLocaleString('fr-CA')} sur ${Number(total||0).toLocaleString('fr-CA')}</div><div class="actions"><button class="btn btn-outline btn-sm" data-action="${action}" data-page="${Math.max(1,p-1)}" ${p<=1?'disabled':''}>← Précédent</button><span class="badge badge-blue">Page ${p} / ${pages}</span><button class="btn btn-outline btn-sm" data-action="${action}" data-page="${Math.min(pages,p+1)}" ${p>=pages?'disabled':''}>Suivant →</button></div></div>`;
  }
  function productPageMarkupV25(){
    const offset=(perfV25.productPage-1)*perfV25.productPageSize;
    const result=PerrasDB.queryProducts(perfV25.productQuery,{offset,limit:perfV25.productPageSize,activeOnly:user.role!=='admin'});
    const pages=pageCountV25(result.total,perfV25.productPageSize);if(perfV25.productPage>pages){perfV25.productPage=pages;return productPageMarkupV25();}
    return `<div class="catalog-performance-note"><strong>${result.total.toLocaleString('fr-CA')} produit(s)</strong><span>Affichage optimisé : ${perfV25.productPageSize} à la fois. Les prix sont calculés uniquement pour les produits visibles.</span></div>${productCardsV18(result.items,'')}${pagerV25(result.total,perfV25.productPage,perfV25.productPageSize,'product-page-v25')}`;
  }
  function renderProductsV25(){
    if(!ensureProductsAsyncFor('products')) return productLoadingMarkup('Chargement des produits');
    const stats=PerrasDB.productStats();
    return `<div class="toolbar"><div class="search"><input id="productSearchV25" value="${esc(perfV25.productQuery)}" autocomplete="off" placeholder="Rechercher par code, description ou catégorie…"></div>${user.role==='admin'?'<button class="btn btn-primary" data-action="new-product">+ Ajouter un produit</button>':''}<span class="small muted">${user.role==='admin'?'Prix coûtant et modification : Admin seulement.':'Fournisseur, Prix Liste et Prix Perras visibles en lecture seulement.'}</span></div><div class="grid grid-4 catalog-mini-kpis"><div class="card kpi"><div class="label">Catalogue</div><div class="value">${stats.total.toLocaleString('fr-CA')}</div></div><div class="card kpi"><div class="label">Actifs</div><div class="value">${stats.active.toLocaleString('fr-CA')}</div></div><div class="card kpi"><div class="label">Stock bas</div><div class="value">${stats.low.toLocaleString('fr-CA')}</div></div><div class="card kpi"><div class="label">Rupture</div><div class="value">${stats.out.toLocaleString('fr-CA')}</div></div></div><div id="productCardsHostV25" style="margin-top:16px">${productPageMarkupV25()}</div>`;
  }
  function inventoryWarehousePageV25(mineTruck){
    const showInactive=user.role==='admin'&&adminUI.inventoryShowInactive,offset=(perfV25.inventoryPage-1)*perfV25.inventoryPageSize;
    const result=PerrasDB.queryProducts(perfV25.inventoryQuery,{offset,limit:perfV25.inventoryPageSize,includeInactive:showInactive,activeOnly:!showInactive,filter:adminUI.inventoryFilter||'all'});
    const pages=pageCountV25(result.total,perfV25.inventoryPageSize);if(perfV25.inventoryPage>pages){perfV25.inventoryPage=pages;return inventoryWarehousePageV25(mineTruck);}
    const stock=PerrasDB.get('truckStock')||[],mineMap=new Map(mineTruck?stock.filter(s=>s.truckId===mineTruck.id).map(s=>[s.productId,Number(s.qty||0)]):[]);
    return `<div class="card"><div class="card-head"><div><h3>${mineTruck?'Entrepôt + mon camion':'Inventaire entrepôt'}</h3><div class="small muted">${result.total.toLocaleString('fr-CA')} produit(s) correspondant aux filtres</div></div><span class="badge badge-blue">100 max / page</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Code</th><th>Produit</th><th>Catégorie</th><th>Entrepôt</th>${mineTruck?'<th>Mon camion</th>':''}<th>Minimum</th><th>État</th>${user.role==='admin'?'<th></th>':''}</tr></thead><tbody>${result.items.map(p=>{const [state,cls]=productState(p);return `<tr class="${p.active===false?'inactive-row':''}"><td><strong>${esc(p.code)}</strong></td><td>${esc(p.description)}</td><td>${esc(p.category)}</td><td>${Number(p.warehouseQty||0)}${p.onOrderQty?`<div class="small muted">+${Number(p.onOrderQty||0)} en commande</div>`:''}</td>${mineTruck?`<td>${mineMap.get(p.id)||0}</td>`:''}<td>${Number(p.minQty||0)}</td><td><span class="badge badge-${cls}">${state}</span></td>${user.role==='admin'?`<td><div class="actions"><button class="btn btn-outline btn-sm" data-action="adjust-stock" data-id="${p.id}">Ajuster</button><button class="btn btn-outline btn-sm" data-action="toggle-product-active" data-id="${p.id}">${p.active===false?'Réactiver':'Inactif'}</button></div></td>`:''}</tr>`}).join('')||'<tr><td colspan="8"><div class="empty">Aucun produit trouvé.</div></td></tr>'}</tbody></table></div>${pagerV25(result.total,perfV25.inventoryPage,perfV25.inventoryPageSize,'inventory-page-v25')}</div>`;
  }
  function truckInventoryPageV25(truck){
    const stock=(PerrasDB.get('truckStock')||[]).filter(s=>s.truckId===truck.id&&Number(s.qty||0)>0),q=PerrasDB.normalizeSearch(perfV25.inventoryQuery),rows=[];
    for(const s of stock){const p=PerrasDB.productById(s.productId);if(!p)continue;const text=PerrasDB.normalizeSearch([p.code,p.description,p.category].join(' '));if(q&&!text.includes(q))continue;rows.push({p,qty:Number(s.qty||0)});}
    const total=rows.length,pages=pageCountV25(total,perfV25.inventoryPageSize);if(perfV25.inventoryPage>pages)perfV25.inventoryPage=pages;const start=(perfV25.inventoryPage-1)*perfV25.inventoryPageSize,visible=rows.slice(start,start+perfV25.inventoryPageSize),tech=byId(getUsers(),truck.assignedUserId),value=rows.reduce((a,x)=>a+x.qty*Number(x.p.listPrice||0),0);
    return `<div class="grid grid-3 truck-kpis"><div class="card kpi"><div class="label">Camion</div><div class="value">${esc(truck.number)}</div><div class="sub">${esc(truck.description||'')}</div></div><div class="card kpi"><div class="label">Technicien assigné</div><div class="value" style="font-size:17px">${esc(tech?.name||'Non assigné')}</div></div><div class="card kpi"><div class="label">Références présentes</div><div class="value">${total.toLocaleString('fr-CA')}</div><div class="sub">Valeur vente ${money(value)}</div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h3>Inventaire — Camion ${esc(truck.number)}</h3><span class="badge badge-blue">${total.toLocaleString('fr-CA')} référence(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Code</th><th>Produit</th><th>Catégorie</th><th>Qté camion</th><th>Entrepôt</th><th>État entrepôt</th></tr></thead><tbody>${visible.map(x=>{const [state,cls]=productState(x.p);return `<tr><td><strong>${esc(x.p.code)}</strong></td><td>${esc(x.p.description)}</td><td>${esc(x.p.category)}</td><td><strong>${x.qty}</strong></td><td>${Number(x.p.warehouseQty||0)}</td><td><span class="badge badge-${cls}">${state}</span></td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty">Aucun produit trouvé dans ce camion.</div></td></tr>'}</tbody></table></div>${pagerV25(total,perfV25.inventoryPage,perfV25.inventoryPageSize,'inventory-page-v25')}</div><div class="card quick-actions-bottom" style="margin-top:16px"><div class="card-head"><h3>Actions rapides — Camion ${esc(truck.number)}</h3></div><div class="card-body"><div class="quick-actions truck-actions"><button class="quick-action" data-route-jump="products">→ Voir les produits</button><button class="quick-action" data-action="inventory-location" data-location="warehouse">→ Retour entrepôt</button>${user.role==='admin'?`<button class="quick-action" data-action="edit-truck" data-id="${truck.id}">→ Modifier le camion</button>`:''}<button class="quick-action" data-route-jump="tools">→ Voir les outils du camion</button></div></div></div>`;
  }
