  content.addEventListener('change',e=>{if(e.target?.id==='punchWeekSelect'){adminUI.punchStart=e.target.value;render();}});

  let googlePullBusy=false;
  async function pullStoredGoogleReviews({rerender=false}={}){
    if(googlePullBusy)return;googlePullBusy=true;
    try{
      const r=await fetch('/api/google-reviews',{headers:{Accept:'application/json'}});if(!r.ok)return;
      const data=await r.json(),arr=PerrasDB.get('googleReviews')||[],byKey=new Map(arr.map(x=>[`${x.businessId||''}:${x.reviewId||x.id}`,x]));let changed=false;
      (data.reviews||[]).forEach(x=>{const key=`${x.businessId||''}:${x.reviewId||x.id}`,old=byKey.get(key);if(!old||JSON.stringify(old)!==JSON.stringify(x)){byKey.set(key,{...(old||{}),...x});changed=true;}});
      if(changed)PerrasDB.set('googleReviews',[...byKey.values()]);
      if(Array.isArray(data.businesses)&&data.businesses.length){const local=PerrasDB.get('googleBusinesses')||[];data.businesses.forEach(b=>{const row=local.find(x=>x.id===b.id||x.name===b.name);if(row)Object.assign(row,b);});PerrasDB.set('googleBusinesses',local);}
      if(changed&&rerender&&location.hash.replace('#','')==='reports'&&adminUI.reportTab==='google')render();
    }catch(_){/* Live Server sans API : mode local */}finally{googlePullBusy=false;}
  }
  setTimeout(()=>pullStoredGoogleReviews({rerender:true}),1200);
