    $('#addManualPOItemV16').onclick=()=>{const desc=prompt('Description de l’article manuel :');if(desc){host.insertAdjacentHTML('beforeend',poDraftItemMarkupV16({description:desc,qty:1,unitCost:0}));bindRemove();}};
    $('#supplierPOFormV16').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),sid=fd.get('supplierId'),sup=byId(suppliers,sid),lineEls=[...host.querySelectorAll('[data-po-draft-row]')];if(!lineEls.length)return alert('Ajoutez au moins un article.');const poItems=lineEls.map(el=>({id:PerrasDB.uid('poi'),productId:el.dataset.productId||'',description:el.dataset.productId?'':el.querySelector('.po-draft-desc strong')?.textContent||'Article manuel',qty:Number(el.querySelector('[data-po-qty]').value||0),receivedQty:0,unitCost:Number(el.querySelector('[data-po-cost]').value||0),backorderResolvedQty:0,requestIds:(el.dataset.requestIds||'').split(',').filter(Boolean)})).filter(x=>x.qty>0);if(!poItems.length)return alert('Aucune quantité valide.');const num=consumeDocNumber('po',fd.get('date')),arr=PerrasDB.get('purchaseOrders')||[],po={id:PerrasDB.uid('po'),number:num,buyerId:user.id,date:fd.get('date'),supplierId:sid,supplier:sup?.name||'',status:'À envoyer',notes:fd.get('notes')||'',items:poItems,total:poItems.reduce((a,x)=>a+x.qty*x.unitCost,0)};arr.unshift(po);PerrasDB.set('purchaseOrders',arr);const prod=PerrasDB.get('products')||[];poItems.forEach(it=>{if(it.productId){const p=byId(prod,it.productId);if(p)p.onOrderQty=Number(p.onOrderQty||0)+Number(it.qty||0);}});PerrasDB.set('products',prod);const req=PerrasDB.get('productRequests')||[],done=new Set(poItems.flatMap(it=>it.requestIds||[]));req.forEach(r=>{if(done.has(r.id)){r.status='Traité';r.purchaseOrderNumber=num;}});PerrasDB.set('productRequests',req);audit('Création','Bon de commande',`${num} — ${poItems.length} ligne(s) groupée(s)`);closeModal();toast(`Bon de commande ${num} créé. Vous pouvez encore l’ouvrir et le compléter.`);adminUI.orderTab='open';render();};
