      const truckTabs=`<div class="tabs report-subtabs" style="margin-bottom:16px"><button class="tab ${adminUI.reportTruck==='all'?'active':''}" data-action="report-truck" data-truck="all">Tous les camions</button>${trucks.map(t=>`<button class="tab ${adminUI.reportTruck===t.id?'active':''}" data-action="report-truck" data-truck="${t.id}">Camion ${esc(t.number)}</button>`).join('')}</div>`;
