    if(toTruck){if(t.truckId)return alert('Cet outil est déjà dans un camion.');t.truckId=mine.id;t.assignedUserId=user.id;audit('Prise','Outil',`${t.name} → Camion ${mine.number} · ${user.name}`);toast(`${t.name} ajouté à votre camion.`);adminUI.toolTab='trucks';}
    else {if(!t.truckId||t.assignedUserId!==user.id)return alert('Seul le technicien qui a pris cet outil peut le remettre.');t.truckId='';t.assignedUserId='';audit('Retour','Outil',`${t.name} → Entrepôt · ${user.name}`);toast(`${t.name} remis à l’entrepôt.`);adminUI.toolTab='warehouse';}
