    $('#winpriserPriceFileV32').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;const prog=$('#winpriserPriceProgressV32');prog.innerHTML='<span class="badge badge-blue">Lecture du fichier…</span>';try{winpriserRowsV31=await readWinpriserFileV31(f);winpriserRowsV31=winpriserRowsV31.filter(r=>Object.values(r).some(v=>String(v??'').trim()));winpriserHeadersV31=[...new Set(winpriserRowsV31.flatMap(r=>Object.keys(r)))];if(!winpriserRowsV31.length)throw new Error('Aucune ligne détectée.');$('#winpriserPriceMappingV32').innerHTML=`<div class="card" style="margin-top:14px"><div class="card-body"><div class="form-grid">${mappingSelectV31('description','Description Winpriser',true)}${mappingSelectV31('listPrice','Nouveau Prix Liste',true)}</div><div class="small muted">Le système analysera d’abord le fichier. Aucun prix ne sera changé avant que vous cliquiez sur « Appliquer les ajustements ».</div><div class="form-actions"><button class="btn btn-primary" id="startWinpriserPriceUpdateV32">Analyser le fichier Winpriser</button></div></div></div>`;document.querySelectorAll('[data-import-map]').forEach(x=>x.onchange=updateWinpriserPricePreviewV32);$('#startWinpriserPriceUpdateV32').onclick=startWinpriserPriceUpdateV32;updateWinpriserPricePreviewV32();prog.innerHTML='<span class="badge badge-green">Fichier prêt pour analyse.</span>';}catch(err){prog.innerHTML=`<span class="badge badge-red">${esc(err.message)}</span>`;}};
