  function updateWinpriserPricePreviewV32(){const host=$('#winpriserPricePreviewV32');if(!host)return;const description=document.querySelector('[data-import-map="description"]')?.value||'',price=document.querySelector('[data-import-map="listPrice"]')?.value||'';host.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>Description Winpriser</th><th>Nouveau Prix Liste</th></tr></thead><tbody>${winpriserRowsV31.slice(0,8).map(r=>`<tr><td>${esc(r[description]??'')}</td><td>${esc(r[price]??'')}</td></tr>`).join('')}</tbody></table></div><div class="small muted">Aperçu des 8 premières lignes · ${winpriserRowsV31.length.toLocaleString('fr-CA')} ligne(s) dans le fichier.</div>`;}
