    return `<div class="card"><div class="card-head"><div><h3>${mineTruck?'Entrepôt + mon camion':'Inventaire entrepôt'}</h3><div class="small muted">${serverInventoryV32.total.toLocaleString('fr-CA')} produit(s) correspondant aux filtres</div></div><span class="badge badge-blue">100 max / page</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Code</th><th>Produit</th><th>Catégorie fournisseur</th><th>Entrepôt</th>${mineTruck?'<th>Mon camion</th>':''}<th>Minimum</th><th>État</th>${user.role==='admin'?'<th></th>':''}</tr></thead><tbody>${serverInventoryV32.items.map(p=>{const [st,cl]=productState(p);return `<tr class="${p.active===false?'inactive-row':''}"><td><strong>${esc(p.code)}</strong></td><td>${esc(p.description||p.code)}</td><td>${esc(supplierCategoryNameV32(p))}</td><td>${Number(p.warehouseQty||0)}${Number(p.onOrderQty||0)>0?`<div class="small muted">+${Number(p.onOrderQty||0)} en commande</div>`:''}</td>${mineTruck?`<td>${mineMap.get(p.id)||0}</td>`:''}<td>${Number(p.minQty||0)}</td><td><span class="badge badge-${cl}">${st}</span></td>${user.role==='admin'?`<td><div class="actions"><button class="btn btn-outline btn-sm" data-action="adjust-server-stock-v32" data-id="${p.id}">Ajuster</button><button class="btn btn-outline btn-sm" data-action="toggle-server-inventory-v32" data-id="${p.id}" data-active="${p.active===false?'0':'1'}">${p.active===false?'Réactiver':'Inactif'}</button></div></td>`:''}</tr>`}).join('')||'<tr><td colspan="8"><div class="empty">Aucun produit trouvé.</div></td></tr>'}</tbody></table></div>${inventoryPagerV32()}</div>`;
