  content.addEventListener('input',e=>{if(e.target.id!=='serverInventorySearchV32')return;clearTimeout(serverInventorySearchTimerV32);serverInventoryV32.q=e.target.value;serverInventoryV32.page=1;serverInventorySearchTimerV32=setTimeout(loadServerInventoryV32,180);});
