  content.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;const act=a.dataset.action;if(act==='supplier-v36-select'){e.preventDefault();supplierUIV36.supplierId=a.dataset.id;supplierUIV36.productPage=1;render();return;}if(act==='supplier-v36-category'){e.preventDefault();supplierUIV36.categoryId=a.dataset.id||'all';supplierUIV36.productPage=1;render();return;}if(act==='supplier-v36-tab'){e.preventDefault();supplierUIV36.tab=a.dataset.tab;supplierUIV36.productPage=1;render();return;}if(act==='supplier-v36-page'){e.preventDefault();supplierUIV36.productPage=Math.max(1,Number(a.dataset.page||1));loadSupplierProductsV36();return;}if(act==='manage-supplier-categories-v36'){e.preventDefault();showSupplierCategoriesV36();return;}},true);
