  /* ===== V39 — RECHERCHE PRODUIT + BT/FACTURE TECH + SUPPRESSION PO RÉUTILISABLE ===== */
  function v39ClientPriceList(c){const cl=byId(getClients(),c?.clientId);return cl?.priceList||'Perras 1';}
  function v39MaterialUnitPrice(product,c){
    if(!product)return 0;
    try{return Number(productPriceInfo(product,v39ClientPriceList(c))?.price||product.perras1Price||product.listPrice||0);}catch(_){return Number(product.perras1Price||product.listPrice||0);}
  }
  function v39TechTruckId(techId){return byId(getUsers(),techId)?.truckId||((user.role==='tech'&&user.id===techId)?user.truckId:'')||'';}
  function v39TruckQty(productId,techId){const truckId=v39TechTruckId(techId);if(!truckId||!productId)return 0;return Number((PerrasDB.get('truckStock')||[]).find(x=>x.truckId===truckId&&x.productId===productId)?.qty||0);}
  function v39ProductFallback(item={}){
    let p=null;try{p=PerrasDB.productById?.(item.productId)||null;}catch(_){}
    return p||{id:item.productId||'',code:item.productCode||'',description:item.description||item.productLabel||'',warehouseQty:item.shopQty||0,listPrice:item.unitPrice||0,perras1Price:item.unitPrice||0};
  }
  function v39MaterialRow(item={},c={}){
    const p=v39ProductFallback(item),code=item.productCode||p.code||'',desc=item.description||p.description||'',price=Number(item.unitPrice ?? v39MaterialUnitPrice(p,c) ?? 0),truck=Number(item.truckQtySnapshot ?? v39TruckQty(item.productId,c.techId) ?? 0),shop=Number(item.shopQty ?? p.warehouseQty ?? 0),rid=PerrasDB.uid('v39mat');
    return `<div class="v39-material-row" data-v39-material data-row-id="${rid}" data-product-id="${esc(item.productId||'')}" data-product-code="${esc(code)}" data-truck-stock="${truck}" data-shop-stock="${shop}">
      <div class="v39-material-product"><label>Produit</label><div class="v39-product-search"><input data-v39-search autocomplete="off" value="${esc(code?`${code} — ${desc}`:'')}" placeholder="Ex. abs 90 2, p-trap 1 1/2…"><div data-v39-results></div></div><input type="hidden" data-v39-product value="${esc(item.productId||'')}"><input type="hidden" data-v39-desc value="${esc(desc)}"></div>
      <div><label>Qté</label><input data-v39-qty type="number" min="0.01" step="0.01" value="${Number(item.qty||1)}"></div>
      <div class="v39-stock-cell"><label>Stock camion</label><strong data-v39-truck>${truck}</strong><small>Shop : <span data-v39-shop>${shop}</span></small></div>
      <div><label>Prix unitaire</label><input data-v39-price type="number" min="0" step="0.01" value="${price.toFixed(2)}"></div>
      <div class="v39-line-total"><label>Total</label><strong data-v39-line-total>${money(Number(item.qty||1)*price)}</strong></div>
      <button type="button" class="btn btn-danger btn-sm v39-remove" data-v39-remove title="Retirer">🗑</button>
    </div>`;
  }
