  function v39StockCheck(c,materials){
    const truckId=v39TechTruckId(c.techId);if(!truckId)return {ok:true,truckId:'',shortages:[]};const stock=PerrasDB.get('truckStock')||[],need=new Map();materials.filter(m=>m.productId).forEach(m=>need.set(m.productId,(need.get(m.productId)||0)+Number(m.qty||0)));const shortages=[];
    for(const [id,qty] of need){const have=Number(stock.find(x=>x.truckId===truckId&&x.productId===id)?.qty||0);if(qty>have+1e-9)shortages.push({id,qty,have,desc:materials.find(m=>m.productId===id)?.description||id});}
    return {ok:!shortages.length,truckId,shortages};
  }
  function v39CommitTruckStock(c,materials){
    if(c.inventoryCommitted)return {ok:true};const check=v39StockCheck(c,materials);if(!check.ok)return check;if(!check.truckId){c.inventoryCommitted='sans-camion';return {ok:true};}
    const stock=PerrasDB.get('truckStock')||[],need=new Map();materials.filter(m=>m.productId).forEach(m=>need.set(m.productId,(need.get(m.productId)||0)+Number(m.qty||0)));
    for(const [id,qty] of need){let row=stock.find(x=>x.truckId===check.truckId&&x.productId===id);if(!row){row={truckId:check.truckId,productId:id,qty:0};stock.push(row);}row.qty=Math.max(0,Number(row.qty||0)-qty);}
    PerrasDB.set('truckStock',stock);c.inventoryCommitted=true;c.inventoryCommittedAt=new Date().toISOString();c.inventoryCommittedTruckId=check.truckId;return {ok:true};
  }
