  function v39FreePoList(prefix){const st=ensureYearNumbering(prefix),node=st.numbering.byYear[prefix],used=new Set([...(PerrasDB.get('purchaseOrders')||[]),...(PerrasDB.get('fieldPOs')||[])].map(x=>x.number).filter(Boolean));node.poFree=Array.isArray(node.poFree)?node.poFree.map(Number).filter(n=>n>0&&Number.isInteger(n)&&!used.has(`${prefix}-${String(n).padStart(4,'0')}`)):[];node.poFree=[...new Set(node.poFree)].sort((a,b)=>a-b);return {st,node};}
  function v39RecyclePoNumber(number){const m=String(number||'').match(/^(\d{2})-(\d{4})$/);if(!m)return;const prefix=m[1],n=Number(m[2]),{st,node}=v39FreePoList(prefix);if(!node.poFree.includes(n))node.poFree.push(n);node.poFree.sort((a,b)=>a-b);PerrasDB.set('settings',st);}
  const v39PeekDocNumberBase=peekDocNumber,v39ConsumeDocNumberBase=consumeDocNumber;
  peekDocNumber=function(kind,date){if(kind!=='po')return v39PeekDocNumberBase(kind,date);const prefix=activeNumberingPrefix(),{node}=v39FreePoList(prefix);if(node.poFree.length)return `${prefix}-${String(node.poFree[0]).padStart(4,'0')}`;return v39PeekDocNumberBase(kind,date);};
  consumeDocNumber=function(kind,date){if(kind!=='po')return v39ConsumeDocNumberBase(kind,date);const prefix=activeNumberingPrefix(),{st,node}=v39FreePoList(prefix);if(node.poFree.length){const n=node.poFree.shift();PerrasDB.set('settings',st);return `${prefix}-${String(n).padStart(4,'0')}`;}return v39ConsumeDocNumberBase(kind,date);};
  async function v39DeletePurchaseOrder(id){
    if(user.role!=='admin')return;const arr=PerrasDB.get('purchaseOrders')||[],po=byId(arr,id);if(!po)return;const received=(po.items||[]).reduce((a,x)=>a+Number(x.receivedQty||0),0);if(received>0)return alert(`Le PO ${po.number} contient déjà ${received} unité(s) reçue(s). Pour protéger l'historique et le stock, il ne peut pas être supprimé.`);if(!confirm(`Supprimer définitivement le PO ${po.number}?\n\n• Les quantités encore "en commande" seront libérées.\n• Le numéro ${po.number} redeviendra disponible.`))return;
    try{await poSyncOnOrderServerV35(po.items||[],po.status||'Fermé',[],'Fermé');}catch(e){return alert('Impossible de remettre les quantités disponibles : '+e.message);}const idx=arr.findIndex(x=>x.id===id);if(idx>=0)arr.splice(idx,1);PerrasDB.set('purchaseOrders',arr);try{await productApiV31('/api/cloud/state',{method:'POST',body:JSON.stringify({key:'purchaseOrders',value:arr})});}catch(_){ }const req=PerrasDB.get('productRequests')||[];req.forEach(r=>{if(r.purchaseOrderNumber===po.number){r.status='À commander';r.purchaseOrderNumber='';}});PerrasDB.set('productRequests',req);v39RecyclePoNumber(po.number);try{await productApiV31('/api/po-number/release',{method:'POST',body:JSON.stringify({number:po.number})});}catch(_){ }audit('Suppression','Bon de commande',`${po.number} — numéro remis disponible`);toast(`PO ${po.number} supprimé. Le numéro est de nouveau disponible.`);render();
  }
  purchaseOrderTable=function(arr,title){return `<div class="card"><div class="card-head"><h3>${esc(title)}</h3><span class="small muted">${arr.length} bon(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>No PO</th><th>Acheteur</th><th>Date</th><th>Fournisseur</th><th>Articles</th><th>Statut</th><th>Total</th><th>Actions</th></tr></thead><tbody>${arr.map(x=>{const outstanding=(x.items||[]).reduce((a,it)=>a+Math.max(0,Number(it.qty||0)-Number(it.receivedQty||0)-Number(it.backorderResolvedQty||0)),0),received=(x.items||[]).reduce((a,it)=>a+Number(it.receivedQty||0),0);return `<tr><td><strong>${esc(x.number)}</strong>${received?`<div class="small muted">${received} reçu</div>`:''}</td><td>${esc(byId(getUsers(),x.buyerId)?.name||'—')}</td><td>${dateOnly(x.date)}</td><td>${esc(x.supplier||byId(PerrasDB.get('suppliers')||[],x.supplierId)?.name||'—')}</td><td>${(x.items||[]).length}<div class="small muted">${outstanding} restant</div></td><td>${badge(x.status)}</td><td>${money(x.total||0)}</td><td><div class="actions"><button class="btn btn-outline btn-sm" data-action="edit-order" data-id="${x.id}">Modifier</button>${['Commandé','Partiel'].includes(x.status)&&outstanding>0?`<button class="btn btn-success btn-sm" data-action="receive-order" data-id="${x.id}">Reçu</button>`:''}<button class="btn btn-danger btn-sm" data-action="delete-po-v39" data-id="${x.id}" ${received>0?'disabled title="PO avec réception : suppression bloquée"':''}>Supprimer</button></div></td></tr>`;}).join('')||'<tr><td colspan="8"><div class="empty">Aucun bon de commande.</div></td></tr>'}</tbody></table></div></div>`;};
  content.addEventListener('click',e=>{const b=e.target.closest('[data-action="delete-po-v39"]');if(!b)return;e.preventDefault();e.stopPropagation();v39DeletePurchaseOrder(b.dataset.id);},true);


