    const arr=PerrasDB.get('fieldPOs')||[],obj={id:PerrasDB.uid('fpo'),number,userId:user.id,supplier:String(fd.get('supplier')||'').trim(),description:String(fd.get('description')||'').trim(),amount:Number(fd.get('amount')||0),receipt:form.elements.receipt.files[0].name,note:fd.get('note'),status:'À vérifier',at:new Date().toISOString(),destination:user.truckId};arr.unshift(obj);PerrasDB.set('fieldPOs',arr);try{await productApiV31('/api/cloud/state',{method:'POST',body:JSON.stringify({key:'fieldPOs',value:arr})});}catch(_){ }try{await productApiV31('/api/po-number/commit',{method:'POST',body:JSON.stringify({number,documentId:obj.id,source:'field-po'})});}catch(_){ }audit('Création','PO terrain',`${number} · ${obj.supplier}`);fieldPoReservedV391='';toast(`PO ${number} enregistré.`);render();
